commands.command:
@'
import assert from 'node:assert/strict';
import {readFileSync,existsSync,readdirSync} from 'node:fs';
import {resolve,dirname} from 'node:path';
import {parseManifest} from './packages/core/src/domain/manifest.ts';
import {parseSkillDocument,documentName,documentDescription} from './packages/core/src/domain/skill-document.ts';
const root=resolve('skills/spring-boot-observability');
const parsed=parseManifest(readFileSync(resolve(root,'skill.yaml'),'utf8'),{strict:true});
assert.deepEqual(parsed.issues,[]);
const doc=parseSkillDocument(readFileSync(resolve(root,'SKILL.md'),'utf8'));
assert.equal(documentName(doc),parsed.manifest.name);
const normalize=s=>s.replace(/\s+/g,' ').trim();
assert.equal(normalize(documentDescription(doc)),normalize(parsed.manifest.description));
for(const file of parsed.manifest.files)assert.ok(existsSync(resolve(root,file)),file);
const files=['SKILL.md',...readdirSync(resolve(root,'references')).filter(f=>f.endsWith('.md')).map(f=>'references/'+f),'assets/observation-fixture/README.md'];
let links=0,external=0;
for(const file of files){
 const absolute=resolve(root,file);
 for(const match of readFileSync(absolute,'utf8').matchAll(/\[[^\]]*\]\(([^)]+)\)/g)){
  const targetValue=match[1].replace(/^</,'').replace(/>$/,'');
  if(/^[a-z]+:/i.test(targetValue)){external++;continue;}
  const [target,anchor]=targetValue.split('#');
  const path=target?resolve(dirname(absolute),target):absolute;
  assert.ok(existsSync(path),targetValue);
  if(anchor){const headings=[...readFileSync(path,'utf8').matchAll(/^#{1,6}\s+(.+)$/gm)].map(m=>m[1].toLowerCase().replace(/[^\p{L}\p{N}\s-]/gu,'').trim().replace(/\s/g,'-'));assert.ok(headings.includes(anchor),targetValue);}
  links++;
 }
}
console.log(JSON.stringify({manifestIssues:parsed.issues.length,name:documentName(doc),version:parsed.manifest.version,descriptionsMatch:true,manifestFilesExist:true,markdownFiles:files.length,localLinks:links,externalLinksObserved:external}));
